class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        if monthly_limit_mib < 0:
            raise ValueError("Monthly limit cannot be negative.")
        self.limit_bytes: float = monthly_limit_mib * 1024 * 1024
        # Mapping from month -> dict of {name: size_bytes}
        self._monthly_uploads: dict[str, dict[str, int]] = {}

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        """month is a string like '2026-01'."""
        if size_bytes <= 0:
            raise ValueError("File size must be greater than 0 bytes.")

        month_files = self._monthly_uploads.setdefault(month, {})

        # If the file already exists in this month with the exact same size,
        # it does not consume additional quota.
        current_file_size = month_files.get(name)
        if current_file_size == size_bytes:
            return

        current_used = sum(month_files.values())
        diff = size_bytes - (current_file_size if current_file_size is not None else 0)

        if current_used + diff > self.limit_bytes:
            raise ValueError("Upload exceeds monthly quota limit.")

        month_files[name] = size_bytes

    def delete(self, name: str, month: str) -> None:
        if month in self._monthly_uploads and name in self._monthly_uploads[month]:
            del self._monthly_uploads[month][name]

    def used_bytes(self, month: str) -> int:
        """How many bytes count towards the quota in the given month."""
        if month not in self._monthly_uploads:
            return 0
        return sum(self._monthly_uploads[month].values())
